SELECT  FROM resource_status_event
WHERE room_id = #{roomId} AND effective_at <= #{at}
ORDER BY effective_at DESC, id DESC LIMIT 1

SELECT  FROM resource_status_event
WHERE seat_id = #{seatId} AND effective_at <= #{at}
ORDER BY effective_at DESC, id DESC LIMIT 1

SELECT  FROM resource_status_event
WHERE room_id = #{roomId} AND effective_at >= #{from} AND effective_at < #{to}
ORDER BY effective_at, id
